      lo, hi = 0, n
      while lo < hi:
        mid = (lo + hi) // 2
        if sums[mid] <= q:
          lo = mid + 1
        else:
          hi = mid
      return lo - 1                    # number of elements with sum ≤ q

    return [bSearch(q) for q in queries]

