class Solution:
    def secondGreaterElement(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = [-1] * n
        first, second = [], []  # first stack for first greater, second stack for second greater
        for i, x in enumerate(nums):
            # Assign second greater to indices waiting in the second stack
            while second and nums[second[-1]] < x:
                ans[second.pop()] = x
            # Move indices that found their first greater into the second stack
            buff = []
            while first and nums[first[-1]] < x:
                buff.append(first.pop())
            while buff:
                second.append(buff.pop())
            # Push current index onto the first stack
            first.append(i)
        return ans

