class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Build index map for list2
        d2 = {name: i for i, name in enumerate(list2)}
        # Collect common restaurants with sum of indices
        candidates = [[i + d2[name], name] for i, name in enumerate(list1) if name in d2]
        if not candidates:
            return []
        # Sort by sum of indices
        candidates.sort()
        min_sum = candidates[0][0]
        # Return all names with minimal sum
        return [item[1] for item in candidates if item[0] == min_sum]

