class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return -1
        low = 0
        high = n
        if n == 1:
            return 0
        while low <= high:
            mid = (low + high) // 2
            # Check if mid is a peak
            if (mid == 0 or nums[mid] >= nums[mid-1]) and (mid == n-1 or nums[mid] >= nums[mid+1]):
                return mid
            # Check if we can go right
            if mid < n-1 and nums[mid] <= nums[mid+1]:
                low = mid + 1
            else:
                high = mid - 1
        return -1
